function placeholderTargetElement(){const target=els.placeholderTargetSelect?.value||'body';if(target==='subject')return els.subjectTemplate;if(target==='cc')return els.ccTemplate;if(target==='bcc')return els.bccTemplate;return q('.editor-tab.is-active')?.dataset.editor==='html'?els.bodyHtmlEditor:els.bodyTemplate;}
