function insertMappedPlaceholder(spec,target=null){applyPlaceholderBuilderMapping(spec);if(target){state.activeEditor=target;insertIntoElement(target,spec.token);syncPlaceholderTargetFromEditor(target);}else insertIntoTemplateTarget(spec.token);renderPlaceholderMappings();}
