  const spec=placeholderBuilderSpec();if(!spec.keyValid){toast('Use a valid placeholder name','Names cannot contain braces, |, line breaks, or start with # or /.','error');return;}if(!spec.fallbackValid){toast('Fallback contains unsupported characters','Fallback values cannot contain braces or line breaks.','error');return;}if(!spec.source){toast('Choose what fills this placeholder','Pick a sheet column, built-in value, or fallback-only source.','error');return;}if(spec.source==='__fallback__'&&!spec.fallback){toast('Add a fallback value','Fallback-only placeholders need a value to insert.','error');return;}insertMappedPlaceholder(spec);toast('Placeholder inserted',`${spec.token} → ${spec.source==='__fallback__'?'fallback':spec.source}`,'success',2600);
