function insertConditionalFromBuilder(){const spec=placeholderBuilderSpec();if(!spec.keyValid||!spec.source||spec.source==='__fallback__'||!spec.fallbackValid)return;applyPlaceholderBuilderMapping(spec);insertIntoTemplateTarget(`{{#if ${spec.key}}}${spec.token}{{/if}}`);renderPlaceholderMappings();toast('Conditional inserted',`Content will render only when ${spec.key} has a value.`,'success',2600);}
function replacePlaceholderTokensInText(text,key,fallback){const escaped=String(key).replace(/[.*+?^${}()|[\]\\]/g,'\\$&');const pattern=new RegExp(`{{\\s*${escaped}\\s*(?:\\|[^{}]*?)?\\s*}}`,'g');return String(text||'').replace(pattern,`{{${key}${fallback?`|${fallback}`:''}}}`);}
