  const value=String(fallback||'').trim();if(!validPlaceholderFallback(value)){toast('Fallback contains unsupported characters','Fallback values cannot contain braces or line breaks.','error');renderPlaceholderMappings();return;}[els.subjectTemplate,els.bodyTemplate,els.ccTemplate,els.bccTemplate].forEach(field=>{field.value=replacePlaceholderTokensInText(field.value,key,value);});[els.bodyHtmlEditor,els.signatureHtmlEditor].forEach(editor=>{const walker=document.createTreeWalker(editor,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(node=>{node.textContent=replacePlaceholderTokensInText(node.textContent,key,value);});});markTemplateDirty();scheduleRender();
