function renderGoogleOauthClient(){const c=state.oauthClient||{};els.googleOauthStatus.innerHTML='';if(c.credential_error){els.connectGoogleButton.disabled=true;els.oauthFileLabel.textContent='Replace OAuth client';els.googleOauthStatus.innerHTML=`<div class="callout warning"><strong>OAuth setup needs attention.</strong><br>${esc(c.credential_error)}</div>`;return;}if(!c.configured){els.connectGoogleButton.disabled=true;els.oauthFileLabel.textContent='Set up & connect';els.googleOauthStatus.innerHTML='<div class="callout neutral"><strong>OAuth 2.1-compatible setup:</strong> choose the Google Desktop app client JSON. MailDesk uses authorization code + PKCE (S256), and stores the client encrypted on this device.</div>';return;}els.connectGoogleButton.disabled=false;els.oauthFileLabel.textContent='Use another OAuth client';const updated=c.updated_at?new Date(c.updated_at).toLocaleString():'saved';els.googleOauthStatus.innerHTML=`<div class="oauth-client-ready"><div><strong>Google OAuth 2.1-compatible</strong><span>${c.pkce?'PKCE S256 · ':''}${esc(c.client_id_hint||'Desktop client')} · updated ${esc(updated)}</span></div><button type="button" class="button ghost small forget-oauth">Forget saved client</button></div>`;q('.forget-oauth',els.googleOauthStatus)?.addEventListener('click',forgetGoogleOauthClient);}
function renderAccounts(){els.accountList.innerHTML='';state.gmailAccounts.forEach(a=>{const d=document.createElement('div');d.className='account-card';const problem=a.credential_error?`<div class="callout warning">${esc(a.credential_error)}</div>`:'',health=a.credential_error?'Reconnect required':a.access_valid?'Access active':a.refresh_available?'Refreshes automatically':'Reconnect required';d.innerHTML=`<div class="account-avatar">${esc(a.email[0]?.toUpperCase()||'G')}</div><div class="account-main"><strong>${esc(a.email)}</strong><span>${esc(health)} · updated ${new Date(a.updated_at).toLocaleString()}</span><div class="account-meta"><span class="pill ${a.gmail===true?'good':''}">Gmail</span><span class="pill ${a.sheets===true?'good':''}">Sheets</span>${a.refresh_available?'<span class="pill good">Offline access</span>':''}</div>${problem}</div><div class="account-actions"><button class="button secondary small check">Check</button><button class="button ghost small reconnect">Reconnect</button><button class="button ghost-danger small disconnect">Disconnect</button></div>`;q('.check',d).addEventListener('click',()=>checkGoogleAccount(a.email));q('.reconnect',d).addEventListener('click',()=>reconnectGoogleAccount(a.email));q('.disconnect',d).addEventListener('click',()=>disconnectAccount(a.email));els.accountList.append(d);});if(!state.gmailAccounts.length)els.accountList.innerHTML='<div class="empty-card">No Gmail accounts connected yet. Set up OAuth once, then connect as many Gmail accounts as you need.</div>';}
function renderBrowserProfiles(){const prev=els.browserProfile.value;els.browserProfile.innerHTML='';state.browserProfiles.forEach(p=>{const o=document.createElement('option');o.value=p.profile_id;const count=(p.gmail_accounts||[]).length;o.textContent=`${p.browser_name} · ${p.profile_name}${count?` · ${count} cached Gmail account${count===1?'':'s'}`:''}`;els.browserProfile.append(o);});if(state.browserProfiles.some(p=>p.profile_id===prev))els.browserProfile.value=prev;updateProfileEmailHints();}
function updateProfileEmailHints(){const p=state.browserProfiles.find(x=>x.profile_id===els.browserProfile.value);els.profileEmails.innerHTML='';(p?.emails||[]).forEach(email=>{const o=document.createElement('option');o.value=email;els.profileEmails.append(o);});renderDetectedBrowserAccounts();}
function renderDetectedBrowserAccounts(){const p=state.browserProfiles.find(x=>x.profile_id===els.browserProfile.value);els.detectedBrowserAccounts.innerHTML='';const accounts=p?.gmail_accounts||[];if(!p){els.browserDetectionHint.textContent='No browser profile is available.';return;}if(!accounts.length){els.detectedBrowserAccounts.innerHTML='<div class="empty-inline">No ordered Gmail session accounts found in this profile.</div>';els.browserDetectionHint.textContent=(p.emails||[]).length?'Profile email hints exist, but Chromium did not persist an ordered Gmail session list. Use the manual fallback and verify it in Gmail.':'Sign in to Gmail in this browser profile, then click Rescan browsers. You can also use the manual fallback.';return;}const age=Number(p.session_cache_age_seconds);const ageText=Number.isFinite(age)?(age<60?'updated moments ago':age<3600?`updated ${Math.max(1,Math.round(age/60))} min ago`:`updated ${Math.round(age/3600)} h ago`):'cache age unknown';els.browserDetectionHint.textContent=`Cached browser account order · ${ageText}. Select an account, then use Verify to confirm the live Gmail page before sending.`;accounts.forEach(account=>{const button=document.createElement('button');button.type='button';button.className='detected-browser-account';button.classList.toggle('is-selected',Number(els.gmailSlot.value)===Number(account.slot)&&els.browserExpectedEmail.value.toLocaleLowerCase()===String(account.email).toLocaleLowerCase());button.innerHTML=`<span class="detected-account-index">${account.slot}</span><span><strong>${esc(account.email)}</strong><small>${account.valid===false?'Session may need sign-in':'Signed-in Gmail account'} · ${esc(p.browser_name)} ${esc(p.profile_name)}</small></span>`;button.addEventListener('click',()=>{els.gmailSlot.value=account.slot;els.browserExpectedEmail.value=account.email;if(!els.browserSenderLabel.value.trim())els.browserSenderLabel.value=account.email;renderDetectedBrowserAccounts();});els.detectedBrowserAccounts.append(button);});}
function selectFirstDetectedBrowserAccount(){const p=state.browserProfiles.find(x=>x.profile_id===els.browserProfile.value);const first=p?.gmail_accounts?.[0];if(first){els.gmailSlot.value=first.slot;els.browserExpectedEmail.value=first.email;}else{els.gmailSlot.value=0;els.browserExpectedEmail.value='';}renderDetectedBrowserAccounts();}
async function rescanBrowserProfiles(){const label=els.rescanBrowserProfilesButton.textContent;els.rescanBrowserProfilesButton.disabled=true;els.rescanBrowserProfilesButton.textContent='Scanning…';try{await refreshAccountsAndBrowsers(true);toast('Browsers rescanned','Detected Gmail accounts were refreshed.','success');}catch(error){toast('Browser scan failed',error.message,'error');}finally{els.rescanBrowserProfilesButton.disabled=false;els.rescanBrowserProfilesButton.textContent=label;}}
function browserAccountPresentation(sender){const profile=state.browserProfiles.find(x=>x.browser_id===sender.browser_id&&x.profile_dir===sender.profile_dir);return{avatar:(profile?.browser_name||sender.browser_id)[0].toUpperCase(),browserName:profile?.browser_name||sender.browser_id,profileName:profile?.profile_name||sender.profile_dir,verification:senderVerificationLabel(sender),fresh:isSenderFresh(sender)};}
function renderBrowserSenders(){els.browserSenderList.innerHTML='';state.browserSenders.forEach(s=>{const account=browserAccountPresentation(s);const d=document.createElement('div');d.className='browser-card';d.innerHTML=`<div class="browser-avatar">${esc(account.avatar)}</div><div class="browser-main"><strong>${esc(s.label)} · ${esc(s.expected_email)}</strong><span>${esc(account.browserName)} · ${esc(account.profileName)}</span><div class="browser-meta"><span class="pill ${account.fresh?'good':''}">${esc(account.verification)}</span></div></div><div class="button-row"><button class="button secondary small verify">Verify</button><button class="button ghost small edit">Edit</button><button class="button ghost-danger small delete">Delete</button></div>`;q('.verify',d).addEventListener('click',()=>startVerifyBrowserSender(s.id));q('.edit',d).addEventListener('click',()=>editBrowserSender(s));q('.delete',d).addEventListener('click',()=>deleteBrowserSender(s.id));els.browserSenderList.append(d);});if(!state.browserSenders.length)els.browserSenderList.innerHTML='<div class="empty-card">No browser accounts yet.</div>';}
function fillAccountSelect(select,accounts,previous){select.innerHTML='';accounts.forEach(a=>{const o=document.createElement('option');o.value=a.email;o.textContent=a.email;select.append(o);});if(accounts.some(a=>a.email===previous))select.value=previous;}
function renderSenderSelects(){const g=els.gmailAccount.value,b=els.browserSender.value,gs=els.googleSheetAccount.value;fillAccountSelect(els.gmailAccount,state.gmailAccounts.filter(a=>a.gmail===true),g);fillAccountSelect(els.googleSheetAccount,state.gmailAccounts.filter(a=>a.sheets===true),gs);els.browserSender.innerHTML='';state.browserSenders.forEach(s=>{const o=document.createElement('option');o.value=s.id;o.textContent=`${s.label} · ${s.expected_email}`;els.browserSender.append(o);});if(state.browserSenders.some(s=>s.id===b))els.browserSender.value=b;updateBrowserSenderSummary();updateFinalSummary();}
function updateBrowserSenderSummary(){const s=state.browserSenders.find(x=>x.id===els.browserSender.value);if(!s){els.browserSenderSummary.innerHTML='<div class="sender-avatar">B</div><div><strong>No browser account selected</strong><span>Add a browser account under Accounts.</span></div><button class="button secondary small" id="verifySelectedBrowserButton2">Configure</button>';q('#verifySelectedBrowserButton2',els.browserSenderSummary)?.addEventListener('click',()=>setView('accounts'));return;}const account=browserAccountPresentation(s);els.browserSenderSummary.innerHTML=`<div class="sender-avatar">${esc(s.expected_email[0].toUpperCase())}</div><div><strong>${esc(s.expected_email)}</strong><span>${esc(account.browserName)} · ${esc(account.profileName)} · ${esc(account.verification)}</span></div><button class="button secondary small" id="verifySelectedBrowserButton2">Verify account</button>`;q('#verifySelectedBrowserButton2',els.browserSenderSummary).addEventListener('click',()=>startVerifyBrowserSender(s.id));}
function isSenderFresh(s){if(!s?.verified_at)return false;const verified=new Date(s.verified_at).getTime();return Number.isFinite(verified)&&Date.now()-verified<30*60*1000;}
function senderVerificationLabel(s){if(!isSenderFresh(s))return 'Verify before use';const expires=new Date(new Date(s.verified_at).getTime()+30*60*1000);return `Verified until ${expires.toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})}`;}
function editBrowserSender(s){els.browserSenderId.value=s.id;els.browserSenderLabel.value=s.label;els.gmailSlot.value=s.gmail_slot;els.browserExpectedEmail.value=s.expected_email;const p=state.browserProfiles.find(x=>x.browser_id===s.browser_id&&x.profile_dir===s.profile_dir);if(p)els.browserProfile.value=p.profile_id;updateProfileEmailHints();renderDetectedBrowserAccounts();window.scrollTo({top:0,behavior:'smooth'});}
