function startTour(){state.tourPreviousFocus=document.activeElement;els.tourOverlay.classList.remove('is-hidden');els.tourOverlay.setAttribute('aria-hidden','false');showTourStep(0);}
function showTourStep(index){state.tourIndex=Math.max(0,Math.min(tourSteps.length-1,index));const step=tourSteps[state.tourIndex];if(step.view)setView(step.view);if(step.view==='campaign'&&step.step)setStep(step.step,{force:true});els.tourStepLabel.textContent=`${state.tourIndex+1} of ${tourSteps.length}`;els.tourTitle.textContent=step.title;els.tourText.textContent=step.text;els.tourBackButton.disabled=state.tourIndex===0;els.tourNextButton.textContent=state.tourIndex===tourSteps.length-1?'Start using MailDesk':'Next';requestAnimationFrame(()=>{const target=q(step.selector);if(target)target.scrollIntoView({block:'center',behavior:'instant'});requestAnimationFrame(()=>{positionTour();els.tourNextButton.focus();});});}
function positionTour(){if(els.tourOverlay.classList.contains('is-hidden'))return;const target=q(tourSteps[state.tourIndex].selector);if(!target)return;const rect=target.getBoundingClientRect(),pad=8;Object.assign(els.tourSpotlight.style,{left:`${Math.max(8,rect.left-pad)}px`,top:`${Math.max(8,rect.top-pad)}px`,width:`${Math.max(24,rect.width+pad*2)}px`,height:`${Math.max(24,rect.height+pad*2)}px`});const cardRect=els.tourCard.getBoundingClientRect();let left=Math.min(Math.max(16,rect.left),innerWidth-cardRect.width-16),top=rect.bottom+16;if(top+cardRect.height>innerHeight-16)top=rect.top-cardRect.height-16;if(top<16){top=Math.max(16,(innerHeight-cardRect.height)/2);left=Math.max(16,(innerWidth-cardRect.width)/2);}Object.assign(els.tourCard.style,{left:`${left}px`,top:`${top}px`});}
function finishTour(){localStorage.setItem(TOUR_STORAGE_KEY,'1');els.tourOverlay.classList.add('is-hidden');els.tourOverlay.setAttribute('aria-hidden','true');els.tourSpotlight.removeAttribute('style');els.tourCard.removeAttribute('style');setView('campaign');setStep(1,{force:true});if(state.tourPreviousFocus?.focus)state.tourPreviousFocus.focus();else els.startTourButton.focus();}
function handleTourKeydown(event){
  if(els.tourOverlay.classList.contains('is-hidden'))return;
  if(event.key==='Escape'){finishTour();return;}
  if(event.key!=='Tab')return;
  const focusable=qsa('button:not(:disabled)',els.tourCard);
  if(!focusable.length)return;
  const first=focusable[0],last=focusable[focusable.length-1];
  if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}
  else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}
}

function saveUiState(){
  const data={mode:currentMode(),throttleMs:els.throttleMs.value,skipDuplicates:els.skipDuplicates.checked,browserSender:els.browserSender.value,gmailAccount:els.gmailAccount.value,sourceTab:state.sourceTab};
  localStorage.setItem('maildesk-ui-state',JSON.stringify(data));
}
function restoreUiState(){
  try{const data=JSON.parse(localStorage.getItem('maildesk-ui-state')||localStorage.getItem('mailmerge-ui-state')||'{}');if(data.mode){const radio=q(`input[name="mode"][value="${data.mode}"]`);if(radio)radio.checked=true;}if(data.throttleMs)els.throttleMs.value=data.throttleMs;if(typeof data.skipDuplicates==='boolean')els.skipDuplicates.checked=data.skipDuplicates;if(data.browserSender&&state.browserSenders.some(x=>x.id===data.browserSender))els.browserSender.value=data.browserSender;if(data.gmailAccount&&state.gmailAccounts.some(x=>x.email===data.gmailAccount))els.gmailAccount.value=data.gmailAccount;if(data.sourceTab)setSourceTab(data.sourceTab);state.unlockedStep=1;setStep(1,{force:true});}catch{state.unlockedStep=1;setStep(1,{force:true});}
}

